    public static void main(String[] args) {
        int a = 0, b = 1;
        for (int i = 2; i <= 4; i++) {
            int next = a + b;
            a = b; b = next;
        }
        System.out.println(b);
        java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
        queue.add(0);
        int[][] graph = {{1}, {}};
        boolean[] visited = {true, false};
        while (!queue.isEmpty()) {
            int v = queue.remove();
            for (int u : graph[v]) if (!visited[u]) { visited[u] = true; queue.add(u); }
        }
        System.out.println(visited[1]);
    }
}

